/** En-tete ASNS embarque — evite les echecs de chargement reseau / cache PWA. */
var ValidationAsnsHeader = (function () {
  "use strict";
  var DATA_URL = "data:image/jpeg;base64,";
  var meta = null;
  function getMeta() {
    if (meta) return Promise.resolve(meta);
    return new Promise(function (resolve, reject) {
      var img = new Image();
      img.onload = function () {
        meta = {
          dataUrl: DATA_URL,
          format: "JPEG",
          w: img.naturalWidth || img.width,
          h: img.naturalHeight || img.height,
        };
        resolve(meta);
      };
      img.onerror = function () {
        reject(new Error("En-tete ASNS embarque illisible."));
      };
      img.src = DATA_URL;
    });
  }
  return { getMeta: getMeta, DATA_URL: DATA_URL };
})();